import{z as r,x as B,o as E,c as m,q as o,j as l,D as n,d as e,s,S as i,b as t}from"./chunks/framework.C8m1ZpeB.js";const x=JSON.parse('{"title":"Softmax 注意力的二次复杂度","description":"","frontmatter":{"title":"Softmax 注意力的二次复杂度","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/attention-quadratic-cost.md","filePath":"llm/attention-quadratic-cost.md","lastUpdated":1791413859000}'),d={name:"llm/attention-quadratic-cost.md"};function p(h,a,D,f,u,F){const A=B("Mermaid");return E(),m("div",null,[a[2]||(a[2]=o('<h1 id="softmax-注意力的二次复杂度" tabindex="-1">Softmax 注意力的二次复杂度 <a class="header-anchor" href="#softmax-注意力的二次复杂度" aria-label="Permalink to &quot;Softmax 注意力的二次复杂度&quot;">​</a></h1><div class="epigraph"><p>自注意力是架构里的瓶颈：它对序列长度是二次的时间与内存复杂度；精确计算仍然可以靠输入输出感知的分块来降低显存墙，但不能把渐近阶改成线性。</p><footer>—— Dao et al., FlashAttention, 2022</footer></div><p><a href="/llm/attention-scale-stability">上一课</a>处理的是分数送到 softmax 之前的尺度。本课假定 SDPA 的公式和数值稳定你都已经会，只问这张表有多贵。每个查询都要对全部键打分，分数矩阵是 \\(n\\times n\\) 的稠密表——二次阶来自「所有序对」，不是来自多头或残差。Vaswani 等人用全连接换恒定跳数的远程依赖；今日数千到百万 token 的上下文里，这张表主导显存与前填延迟。精确算法能优化 IO，不能改渐近阶。稀疏与线性注意力是后面课序的替换方案。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/sdpa">SDPA</a> 的主导项有两处矩阵乘：\\(QK^\\top\\) 花费 \\(O(n^2 d_k)\\)，\\(AV\\) 花费 \\(O(n^2 d_v)\\)。若物化分数与权重，还要 \\(O(n^2)\\) 的读写。当 \\(n\\gg d_k\\) 时，二次项压过投影的 \\(O(nd^2)\\)。<a href="/llm/mha">多头</a>并不改变阶：头数 \\(h\\) 与 \\(d_k\\) 的乘积通常等于模型宽，总代价仍是</p> \\[O\\bigl(L\\, n^{2}\\, d_{\\mathrm{model}}\\bigr) \\]<p>量级。</p><p>更尖锐的是内存墙。现代 GPU 上算术吞吐远高于把 \\(n\\times n\\) 张量搬进搬出高带宽存储器的能力。朴素实现先写出 \\(S\\)，再 softmax 成 \\(A\\)，再乘 \\(V\\)，三次大块访问。\\(n=8\\times 10^3\\) 时一张 FP16 权重矩阵约 128MB，再乘层数与头数，激活显存会先于算力爆掉。二次复杂度因此首先表现为「存不下、搬不动」，其次才是「算不完」。</p><p><span class="marginnote">数字实例：128MB 是怎么来的——\\(n^2\\) 个数 \\(\\times\\) FP16 每数 2 字节 \\(= 8000^2\\times2\\,\\text{B}\\approx128\\) MB，这还只是<strong>一个头、一层</strong>的一张表。上下文拉到 32k，同一张表变 2GB；乘上 40 层、32 头，就是天文数字。这就是「显存先爆」比「算不完」更早发生的原因。</span></p><h3 id="前填与解码的代价形态不同" tabindex="-1">前填与解码的代价形态不同 <a class="header-anchor" href="#前填与解码的代价形态不同" aria-label="Permalink to &quot;前填与解码的代价形态不同&quot;">​</a></h3><p>训练和推理前填（prefill）对整段提示一次性做自注意力，必须为每个查询看见当前合法的全部键，二次项完整出现。自回归解码每步只有 \\(1\\) 条新查询，对已缓存的 \\(t\\) 个键打分，步代价是 \\(O(t d)\\)，生成 \\(n\\) 个词的总和仍是 \\(O(n^2 d)\\)。KV 缓存消灭的是重复投影，不是二次求和：第 \\(n\\) 步仍然要对 \\(n\\) 个键做点积。缓存还把二次问题转成容量问题——键值表按 \\(n\\) 线性增长，直到显存放不下。</p><p><span class="marginnote">KV 缓存到底吃多少？以 40 层、\\(d_{\\mathrm{model}}=4096\\)、FP16 存 K 和 V 估算：每 token 每层 \\(2\\times4096\\times2\\,\\text{B}=16\\) KB，全模型 640 KB/token。上下文 10 万 token 就要约 64 GB 显存——还没算权重。这就是为什么长上下文服务都在压 KV 宽度（GQA、MLA）或压历史长度（滑窗）。</span></p><p><span class="marginnote">有人说「解码是线性的」。单步相对当前长度是线性，完整生成相对最终长度仍是二次。长短前缀的服务差异主要来自前填的 \\(n^2\\) 与缓存占用，而不是解码循环突然变成 \\(O(n)\\) 总代价。讨论吞吐时要把「步」和「整段」分开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>精确 softmax 注意力可以不物化 \\(n\\times n\\) 矩阵。FlashAttention 的做法是把 \\(Q\\) 按行块、\\(K,V\\) 按列块装入片上存储，对每个查询块累加与各键块的点积，用在线 softmax 维护行最大值与归一化因子，块间只传递少量统计量。输出块写回时已经是加权后的值，HBM 上不再落下一张完整 \\(A\\)。数学结果与朴素算法相同，复杂度阶仍是 \\(O(n^2 d)\\)，但 HBM 访问降到与 \\(n,d\\) 更接近线性的项，受片上块大小约束。</p><p>因果掩码与 FlashAttention 兼容：下三角以外的块可以直接跳过，大约减半前填计算。这是常数因子，不是降阶。padding 同理，只能跳过明显空块。只要连通性仍是稠密前缀或稠密全连接，渐近二次不会消失。</p><h3 id="为何「精确」无法降阶" tabindex="-1">为何「精确」无法降阶 <a class="header-anchor" href="#为何「精确」无法降阶" aria-label="Permalink to &quot;为何「精确」无法降阶&quot;">​</a></h3><p>softmax 的分母依赖整行所有键。任意位置的键都可能成为该行最大值或贡献不可忽略的质量，于是一般情形下必须触及全部 \\(n\\) 个键。除非改变核函数（线性注意力把 \\(\\mathrm{softmax}(q^\\top k)\\) 换成 \\(\\phi(q)^\\top\\phi(k)\\) 从而先聚合 \\(\\sum \\phi(k)v\\)），或改变连通性（窗口、块稀疏），否则信息论上就需要 \\(\\Theta(n^2)\\) 次交互。FlashAttention 优化的是常数与内存层次，承认这一下界。</p>',18)),(E(),l(i,null,{default:n(()=>[s(A,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22Query%20%E5%88%86%E5%9D%97%22%5D%20--%3E%20SRAM%5B%22%E7%89%87%E4%B8%8A%E7%B4%AF%E5%8A%A0%E7%82%B9%E7%A7%AF%22%5D%0A%20%20K%5B%22Key%20%E5%88%86%E5%9D%97%22%5D%20--%3E%20SRAM%0A%20%20V%5B%22Value%20%E5%88%86%E5%9D%97%22%5D%20--%3E%20SRAM%0A%20%20SRAM%20--%3E%20STAT%5B%22%E5%9C%A8%E7%BA%BF%E6%9C%80%E5%A4%A7%E5%80%BC%E4%B8%8E%E5%BD%92%E4%B8%80%E5%8C%96%E5%9B%A0%E5%AD%90%22%5D%0A%20%20STAT%20--%3E%20SRAM%0A%20%20SRAM%20--%3E%20OUT%5B%22%E5%86%99%E5%87%BA%E5%8A%A0%E6%9D%83%E7%BB%93%E6%9E%9C%22%5D%0A%20%20OUT%20--%3E%20HBM%5B%22%E9%AB%98%E5%B8%A6%E5%AE%BD%E5%AD%98%E5%82%A8%E4%B8%AD%E6%97%A0%E5%AE%8C%E6%95%B4%E5%88%86%E6%95%B0%E7%9F%A9%E9%98%B5%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"二次项的结构来自行随机矩阵 \\(A\\)。\\(A\\) 的每一行是长度为 \\(n\\) 的分布，与 \\(V\\) 相乘是一次全表查询。多头复制了 \\(h\\) 张这样的表，但每张更「窄」，总交互次数仍按 \\(n^2\\) 计。交叉注意力把其中一维换成记忆长度 \\(m\\)，代价 \\(O(nm)\\)；当 \\(m\\sim n\\) 时同样是二次。编码器-解码器架构在源很长、目标尚短时，\\(nm\\) 可能暂时低于目标自注意力的 \\(n^2\\)，这只是两个长度的不对称，不是降阶算法。",-1)),a[5]||(a[5]=t("p",null,"带宽视角下，解码第 \\(t\\) 步读取 KV 缓存的字节量为",-1)),a[6]||(a[6]=e(" \\[\\Theta\\bigl(t \\cdot h \\cdot d_k\\bigr). \\]",-1)),a[7]||(a[7]=t("p",null,"\\(t\\) 增大后，这一读带宽成为单请求延迟的主项，算力反而空闲。二次代价于是在解码阶段改头换面：从「算 \\(n^2\\) 次乘加」变成「搬 \\(n\\) 段历史」。MQA、GQA、MLA 压缩的是每步要搬的历史宽度，滑动窗口压缩的是历史长度，两条线都在打二次代价的存储形态，而不是改 softmax 定义。",-1)),a[8]||(a[8]=t("p",null,[t("span",{class:"marginnote"},"直觉类比：自回归解码像续写一部长篇小说，每写一个新句子前都要把前面全部手稿重读一遍。写到第 1 章很快，写到第 90 章每句都先读完 90 章——慢的不是「想」而是「翻稿子」（带宽），这也是为什么解码后期 GPU 的算力大量闲置。")],-1)),a[9]||(a[9]=t("p",null,[t("span",{class:"marginnote"},"混合专家、更大的前馈层会增加 \\(O(nd^2)\\) 的线性项。当 \\(n\\) 中等、\\(d\\) 很大时，前馈可以重新成为瓶颈，注意力的二次项反而不显眼。二次是长度的函数：上下文从 4k 拉到 128k，注意力会迅速回到主导地位。比较架构开销必须同时报 \\(n\\) 和 \\(d\\)。")],-1)),(E(),l(i,null,{default:n(()=>[s(A,{id:"mermaid-70",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q2%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%E4%BA%8C%E6%AC%A1%E4%BB%A3%E4%BB%B7%EF%BC%8C%E4%B8%A4%E7%A7%8D%E5%BD%A2%E6%80%81%22%5D%20--%3E%20PF%5B%22%E5%89%8D%E5%A1%AB%EF%BC%9A%E4%B8%80%E6%AC%A1%E4%BB%98%E6%B8%85%20n%C3%97n%20%E5%85%A8%E8%A1%A8%EF%BC%8C%E5%90%83%E7%AE%97%E5%8A%9B%22%5D%0A%20%20Q2%20--%3E%20DC%5B%22%E8%A7%A3%E7%A0%81%EF%BC%9A%E6%AF%8F%E6%AD%A5%E6%90%AC%20t%20%E6%AE%B5%20KV%EF%BC%8C%E5%90%83%E5%B8%A6%E5%AE%BD%22%5D%0A%20%20PF%20--%3E%20SYS%5B%22%E7%B3%BB%E7%BB%9F%E5%B1%82%E5%87%8F%E6%9C%89%E6%95%88%20n%EF%BC%9A%E6%A3%80%E7%B4%A2%E3%80%81%E6%91%98%E8%A6%81%22%5D%0A%20%20DC%20--%3E%20WID%5B%22%E5%8E%8B%E5%AE%BD%E5%BA%A6%EF%BC%9AMQA%20%2F%20GQA%20%2F%20MLA%22%5D%0A%20%20DC%20--%3E%20LEN%5B%22%E5%8E%8B%E9%95%BF%E5%BA%A6%EF%BC%9A%E6%BB%91%E5%8A%A8%E7%AA%97%E5%8F%A3%22%5D%0A%20%20SYS%20--%3E%20SAME%5B%22%E7%A8%A0%E5%AF%86%20softmax%20%E4%BB%8D%E6%98%AF%E4%BA%8C%E6%AC%A1%EF%BC%9A%E6%94%B9%E7%9A%84%E9%83%BD%E6%98%AF%E5%AD%98%E5%82%A8%E5%BD%A2%E6%80%81%EF%BC%8C%E4%B8%8D%E6%98%AF%E9%98%B6%22%5D%0A%20%20WID%20--%3E%20SAME%0A%20%20LEN%20--%3E%20SAME%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[10]||(a[10]=o('<h3 id="激活重计算与训练显存" tabindex="-1">激活重计算与训练显存 <a class="header-anchor" href="#激活重计算与训练显存" aria-label="Permalink to &quot;激活重计算与训练显存&quot;">​</a></h3><p>训练还要存反向所需的中间量。朴素实现保存 \\(A\\) 会再付一张 \\(n^2\\) 的显存。FlashAttention 的反向重算各块的注意力，用更少的 HBM 换更多算术，符合「算术便宜、搬运贵」。重计算不降低前向 FLOPs 的阶，只改变训练能否在给定显存下跑到该 \\(n\\)。梯度检查点叠在层间，是另一层用时间换空间，对象是整层激活，不只是注意力矩阵。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>接受二次、把实现做到 IO 感知，是目前解码器只模型的默认路径：公式不变，内核换 FlashAttention 及其后续。要在渐近上离开二次，必须放弃稠密 softmax 或放弃全可见集合。窗口注意力把 \\(n^2\\) 换成 \\(n\\times w\\)；线性注意力把核换成可分解形式；状态空间把交互变成递推。它们各自有逼近误差与训练稳定性代价，不能假装仍是同一条注意力。</p><p>服务系统里常把前填与解码拆开调度：前填吃计算、解码吃带宽。批处理多个短请求可以摊掉内核启动，但帮不上单个超长请求的 \\(n^2\\)。对超长上下文，先用检索或摘要把有效 \\(n\\) 降下来，往往比在稠密 softmax 内部再抠常数更有效。那是系统层减 \\(n\\)，公式层仍然二次。</p><p><span class="marginnote">宣称「线性复杂度注意力」时，应核对其是否仍对全部 token 做 softmax 归一化。若分母仍依赖全序列且核不可分，实现再快也只是常数优化。真正的线性方法会先对键值做与查询无关的聚合，再与查询相乘。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>稠密 softmax 注意力对长度为 \\(n\\) 的序列需要 \\(\\Theta(n^2)\\) 次查询-键交互，来自全序对打分这一规定。</li><li>前填一次性付清二次项；解码逐步付，总和仍二次，KV 缓存只避免重复投影。</li><li>物化 \\(n\\times n\\) 权重会撞上显存与 HBM 带宽；FlashAttention 用分块在线 softmax 保持精确结果并降低搬运。</li><li>IO 优化不改变渐近阶；降阶必须改核函数或改可见集合。</li><li>解码阶段二次代价常表现为读缓存的带宽，头压缩与缩短历史是两条工程出路。</li><li>比较是否瓶颈时要同时看序列长度与模型宽度，中等 \\(n\\) 下前馈可能更重。</li><li>出处：Vaswani et al., <em>Attention Is All You Need</em>, NeurIPS 2017；Dao et al., <em>FlashAttention</em>, 2022，以及 Dao, <em>FlashAttention-2</em>, 2023。</li></ul>',8))])}const S=r(d,[["render",p]]);export{x as __pageData,S as default};
